    func createRectangle()-> UIBezierPath {//Americas map frame drawing
       var path = UIBezierPath()
       path.move(to: CGPoint(x: 0.0, y: 0.0))
       path.addLine(to: CGPoint(x: 0.0, y:580.0))
       path.addLine(to: CGPoint(x:390.0 , y:580.0))
       path.addLine(to: CGPoint(x:390.0, y: 0.0))
       path.close()
       path = UIBezierPath(roundedRect:path.bounds,cornerRadius: 4.0)
       return path
   }
   

